import os
from datetime import datetime, timezone
from typing import Any, Dict, Optional

from datadog_api_client import ApiClient, Configuration
from datadog_api_client.v1.api.metrics_api import MetricsApi


def get_metric_aggregates(
    metric_name: str,
    start: datetime,
    end: datetime,
    space_aggregation: str = "avg",
    time_aggregation: str = "avg",
    api_key: Optional[str] = None,
    app_key: Optional[str] = None,
) -> Dict[str, Any]:
    api_key = api_key or os.environ["DATADOG_API_KEY"]
    app_key = app_key or os.environ["DATADOG_APP_KEY"]

    if start.tzinfo is None:
        start = start.replace(tzinfo=timezone.utc)
    if end.tzinfo is None:
        end = end.replace(tzinfo=timezone.utc)

    config = Configuration()
    config.api_key["apiKeyAuth"] = api_key
    config.api_key["appKeyAuth"] = app_key

    query = f"{space_aggregation}:{metric_name}{{*}}"

    with ApiClient(config) as api_client:
        api = MetricsApi(api_client)
        response = api.query_metrics(
            _from=int(start.timestamp()),
            to=int(end.timestamp()),
            query=query,
        )

    series = getattr(response, "series", None) or []
    pointlists = []
    scoped_series = []

    for item in series:
        points = getattr(item, "pointlist", None) or []
        clean_points = [
            {"timestamp_ms": int(p[0]), "value": p[1]}
            for p in points
            if p and len(p) >= 2 and p[1] is not None
        ]
        pointlists.extend([p["value"] for p in clean_points])
        scoped_series.append(
            {
                "metric": getattr(item, "metric", None),
                "scope": getattr(item, "scope", None),
                "unit": [
                    {
                        "family": getattr(u, "family", None),
                        "name": getattr(u, "name", None),
                        "plural": getattr(u, "plural", None),
                        "scale_factor": getattr(u, "scale_factor", None),
                    }
                    for u in (getattr(item, "unit", None) or [])
                ],
                "points": clean_points,
            }
        )

    aggregate_value = None
    if pointlists:
        if time_aggregation == "avg":
            aggregate_value = sum(pointlists) / len(pointlists)
        elif time_aggregation == "sum":
            aggregate_value = sum(pointlists)
        elif time_aggregation == "min":
            aggregate_value = min(pointlists)
        elif time_aggregation == "max":
            aggregate_value = max(pointlists)
        else:
            raise ValueError("time_aggregation must be one of: avg, sum, min, max")

    return {
        "provider": "Datadog",
        "metric_name": metric_name,
        "query": query,
        "start": start.isoformat(),
        "end": end.isoformat(),
        "space_aggregation": space_aggregation,
        "time_aggregation": time_aggregation,
        "aggregate_value": aggregate_value,
        "series_count": len(scoped_series),
        "series": scoped_series,
    }
